-- Storefront announcement bar + editable homepage meta (store_settings) and the Hero-derived Open
-- Graph image key (storefront_homepage_sections). Generated by drizzle-kit, then read.
--
-- Backward compatibility with the previous release (CLAUDE.md expand/contract): additive only.
-- Every new column is nullable or has a default, so the previous release's INSERT/UPDATE
-- statements (which name only the columns they know) keep working and never touch these. The
-- singleton store_settings row picks up announcement_bar_enabled = true and the default text
-- through the column defaults. The CHECKs only bound columns the previous release never writes.
-- Rollback leaves the columns in place, unread by the older image.
ALTER TABLE "store_settings" ADD COLUMN "announcement_bar_enabled" boolean DEFAULT true NOT NULL;--> statement-breakpoint
ALTER TABLE "store_settings" ADD COLUMN "announcement_bar_text" text DEFAULT 'Gratis Ongkir Ke Seluruh Indonesia';--> statement-breakpoint
ALTER TABLE "store_settings" ADD COLUMN "homepage_meta_title" text;--> statement-breakpoint
ALTER TABLE "store_settings" ADD COLUMN "homepage_meta_description" text;--> statement-breakpoint
ALTER TABLE "storefront_homepage_sections" ADD COLUMN "published_og_image_key" text;--> statement-breakpoint
ALTER TABLE "store_settings" ADD CONSTRAINT "store_settings_announcement_bar_text_length_check" CHECK (char_length("store_settings"."announcement_bar_text") <= 40);--> statement-breakpoint
ALTER TABLE "store_settings" ADD CONSTRAINT "store_settings_homepage_meta_title_length_check" CHECK (char_length("store_settings"."homepage_meta_title") <= 80);--> statement-breakpoint
ALTER TABLE "store_settings" ADD CONSTRAINT "store_settings_homepage_meta_description_length_check" CHECK (char_length("store_settings"."homepage_meta_description") <= 200);